"use client"

import { Toast as ToastPrimitive } from "@base-ui/react/toast"
import {
  AlertTriangle,
  CheckCircle,
  InfoCircle,
  LoaderLines,
  X,
  XCircle,
} from "@boxicons/react"
import { cn } from "cn"
import { memo } from "react"

import { Button } from "./button"
import { type PaperVariant, useSketchOutline } from "./sketch-provider"

const TOAST_ICONS = {
  error: memo(XCircle),
  info: memo(InfoCircle),
  loading: memo(LoaderLines),
  success: memo(CheckCircle),
  warning: memo(AlertTriangle),
} as const

const CloseIcon = memo(X)

const TYPE_TINTS =
  "data-[type=error]:[--toast-tint:var(--destructive)] data-[type=info]:[--toast-tint:var(--color-sky-600)] data-[type=loading]:[--toast-tint:var(--muted-foreground)] data-[type=success]:[--toast-tint:var(--color-emerald-600)] data-[type=warning]:[--toast-tint:var(--color-amber-600)] dark:data-[type=info]:[--toast-tint:var(--color-sky-400)] dark:data-[type=success]:[--toast-tint:var(--color-emerald-400)] dark:data-[type=warning]:[--toast-tint:var(--color-amber-400)]"

const PAPER_TOAST =
  "[--paper-opacity:0.25] [--paper-pattern:var(--toast-tint)] [--toast-icon:var(--toast-tint)] before:rounded-lg"

export type ToastData = {
  variant?: PaperVariant
}

const toast = ToastPrimitive.createToastManager<ToastData>()

function ToastProvider({ ...props }: ToastPrimitive.Provider.Props) {
  return <ToastPrimitive.Provider {...props} />
}

function ToastPortal({ ...props }: ToastPrimitive.Portal.Props) {
  return <ToastPrimitive.Portal data-slot="toast-portal" {...props} />
}

function ToastViewport({ className, ...props }: ToastPrimitive.Viewport.Props) {
  return (
    <ToastPrimitive.Viewport
      data-slot="toast-viewport"
      className={cn(
        "pointer-events-none fixed inset-x-4 bottom-4 z-50 mx-auto w-auto max-w-sm outline-none sm:right-4 sm:left-auto sm:mx-0 sm:w-full",
        className
      )}
      {...props}
    />
  )
}

function Toast({
  children,
  className,
  variant = "default",
  ...props
}: ToastPrimitive.Root.Props & { variant?: PaperVariant }) {
  const sketchOutline = useSketchOutline()

  return (
    <ToastPrimitive.Root
      data-slot="toast"
      data-paper={variant}
      className={cn(
        "group/toast pointer-events-auto absolute right-0 bottom-0 isolate z-[calc(1000-var(--toast-index))] w-full origin-bottom rounded-lg bg-popover text-popover-foreground will-change-transform outline-none select-none [--sketch-stroke:var(--toast-tint)] [--toast-icon:var(--muted-foreground)] [--toast-tint:var(--border)] focus-visible:ring-3 focus-visible:ring-ring/50 data-[type=error]:[--toast-icon:var(--destructive)] data-[type=error]:[--toast-tint:var(--destructive)] [&>[data-sketch-outline]]:-z-10",
        variant !== "default" && cn(TYPE_TINTS, PAPER_TOAST),
        "[--gap:0.75rem] [--height:var(--toast-frontmost-height,var(--toast-height))] [--offset-y:calc(var(--toast-offset-y)*-1+calc(var(--toast-index)*var(--gap)*-1)+var(--toast-swipe-movement-y))] [--peek:0.75rem] [--scale:calc(max(0,1-(var(--toast-index)*0.1)))] [--shrink:calc(1-var(--scale))]",
        "h-(--height) [transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)-(var(--toast-index)*var(--peek))-(var(--shrink)*var(--height))))_scale(var(--scale))] [transition:transform_500ms_cubic-bezier(0.22,1,0.36,1),opacity_500ms,height_150ms]",
        "after:absolute after:top-full after:left-0 after:h-[calc(var(--gap)+1px)] after:w-full after:content-['']",
        "data-expanded:h-(--toast-height) data-expanded:[transform:translateX(var(--toast-swipe-movement-x))_translateY(var(--offset-y))]",
        "data-limited:opacity-0 data-starting-style:[transform:translateY(150%)]",
        "[&[data-ending-style]:not([data-limited]):not([data-swipe-direction])]:[transform:translateY(150%)]",
        "data-ending-style:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
        "data-ending-style:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
        "data-ending-style:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
        "data-ending-style:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
        "data-expanded:data-ending-style:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
        "data-expanded:data-ending-style:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
        "data-expanded:data-ending-style:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
        "data-expanded:data-ending-style:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
        className
      )}
      {...props}
    >
      {children}
      <svg
        aria-hidden="true"
        data-sketch-outline
        ref={sketchOutline.ref}
        style={sketchOutline.style}
      />
    </ToastPrimitive.Root>
  )
}

function ToastContent({ className, ...props }: ToastPrimitive.Content.Props) {
  return (
    <ToastPrimitive.Content
      data-slot="toast-content"
      className={cn(
        "flex h-full items-center gap-3 overflow-clip [overflow-clip-margin:6px] p-4 transition-opacity duration-250 ease-[cubic-bezier(0.22,1,0.36,1)] data-behind:opacity-0 data-expanded:opacity-100",
        className
      )}
      {...props}
    />
  )
}

function ToastTitle({ className, ...props }: ToastPrimitive.Title.Props) {
  return (
    <ToastPrimitive.Title
      data-slot="toast-title"
      className={cn("text-sm font-medium", className)}
      {...props}
    />
  )
}

function ToastDescription({
  className,
  ...props
}: ToastPrimitive.Description.Props) {
  return (
    <ToastPrimitive.Description
      data-slot="toast-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

function ToastAction({
  className,
  render = <Button variant="outline" size="sm" />,
  ...props
}: ToastPrimitive.Action.Props) {
  return (
    <ToastPrimitive.Action
      data-slot="toast-action"
      render={render}
      className={cn("shrink-0 [--sketch-stroke:var(--border)]", className)}
      {...props}
    />
  )
}

function ToastClose({
  className,
  children,
  render = <Button variant="ghost" size="icon-sm" />,
  ...props
}: ToastPrimitive.Close.Props) {
  return (
    <ToastPrimitive.Close
      data-slot="toast-close"
      aria-label="Close toast"
      render={render}
      className={cn(
        "shrink-0 text-muted-foreground [--sketch-stroke:var(--border)] hover:text-foreground",
        className
      )}
      {...props}
    >
      {children ?? <CloseIcon />}
    </ToastPrimitive.Close>
  )
}

function ToastIcon({ type }: { type: string | undefined }) {
  const Icon = type ? TOAST_ICONS[type as keyof typeof TOAST_ICONS] : undefined

  if (!Icon) {
    return null
  }

  return (
    <span
      data-slot="toast-icon"
      className="shrink-0 text-(--toast-icon) [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 group-hover/toast:[&_svg]:animate-[sketch-icon-wiggle_180ms_ease-in-out_infinite] motion-reduce:group-hover/toast:[&_svg]:animate-none"
    >
      <Icon className={cn(type === "loading" && "animate-spin")} />
    </span>
  )
}

function ToastList() {
  const { toasts } = ToastPrimitive.useToastManager<ToastData>()

  return toasts.map((toastItem) => (
    <Toast
      key={toastItem.id}
      toast={toastItem}
      variant={toastItem.data?.variant}
    >
      <ToastContent>
        <ToastIcon type={toastItem.type} />
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <ToastTitle />
          <ToastDescription />
        </div>
        <ToastAction />
        <ToastClose />
      </ToastContent>
    </Toast>
  ))
}

function Toaster({
  children,
  toastManager = toast,
  ...props
}: ToastPrimitive.Provider.Props) {
  return (
    <ToastProvider toastManager={toastManager} {...props}>
      {children}
      <ToastPortal>
        <ToastViewport>
          <ToastList />
        </ToastViewport>
      </ToastPortal>
    </ToastProvider>
  )
}

const createToastManager = ToastPrimitive.createToastManager
const useToastManager = ToastPrimitive.useToastManager

export {
  Toast,
  ToastAction,
  ToastClose,
  ToastContent,
  ToastDescription,
  ToastPortal,
  ToastProvider,
  ToastTitle,
  ToastViewport,
  Toaster,
  createToastManager,
  toast,
  useToastManager,
}
